3. **数组大小**：
   - `N=100`可能偏小，建议根据题目要求调整（题目中N,V,M通常≤1000）

### 修正后的代码：

```cpp
#include <bits/stdc++.h>
using namespace std;
const int N=1010;  // 根据题目要求调整大小
int n,V,M;
int v[N],w[N],m[N];
int mem[N][N][N];

int dfs(int x,int spV,int spM) {
    if (x>n) return 0;
    if(mem[x][spV][spM]) return mem[x][spV][spM];  // 修正记忆化检查

    int sum = dfs(x+1,spV,spM);  // 不选当前物品

    if(spV>=v[x] && spM>=m[x]) {
        sum = max(sum, dfs(x+1,spV-v[x],spM-m[x]) + w[x]);  // 修正w[x]位置
    }

    mem[x][spV][spM] = sum;
    return sum;
}

int main() {
    cin>>n>>V>>M;
    for(int i=1;i<=n;i++) {
        cin>>v[i]>>m[i]>>w[i];
    }
    cout<<dfs(1,V,M)<<endl;
    return 0;
}
```

### 优化建议：

1. **迭代式DP解法**（更推荐）：
```cpp
#include <bits/stdc++.h>
using namespace std;
const int N=1010;
int f[N][N];  // f[j][k]表示体积j，重量k时的最大价值

int main() {
    int n,V,M;
    cin>>n>>V>>M;

    for(int i=1;i<=n;i++) {
        int v,m,w;
        cin>>v>>m>>w;
        for(int j=V;j>=v;j--)
            for(int k=M;k>=m;k--)
                f[j][k]=max(f[j][k],f[j-v][k-m]+w);
    }

    cout<<f[V][M]<<endl;
    return 0;
}
```

