                f[j][k]=max(f[j][k],f[j-v][k-m]+w);
    }

    cout<<f[V][M]<<endl;
    return 0;
}

你的代码混合了两种解法（记忆化搜索和迭代DP），但存在几个关键问题：

### 主要问题：

1. **记忆化搜索部分**：
   - 完全背包的状态转移方程错误：`dfs(x,spV-v[x])`应该改为`dfs(x,spV-v[x])`（当前行不变）
   - 但你的记忆化搜索实现的是01背包的逻辑（x+1）

2. **迭代DP部分**：
   - 你写的是01背包的状态转移（使用i+1）
   - 完全背包应该用同一行的`f[i][j-v[i]]`更新

3. **代码混杂**：
   - 同时保留了记忆化搜索和迭代DP的实现，但只使用了迭代DP的输出

### 修正建议：

#### 方案1：正确的记忆化搜索（完全背包）
```cpp
int dfs(int x, int spV) {
    if(x > n) return 0;
    if(mem[x][spV]) return mem[x][spV];

    int sum = dfs(x+1, spV); // 不选当前物品
    if(spV >= v[x]) {
        sum = max(sum, dfs(x, spV-v[x]) + w[x]); // 关键区别：仍然是x不是x+1
    }
    return mem[x][spV] = sum;
}
```

#### 方案2：正确的迭代DP（完全背包）
```cpp
for(int i = 1; i <= n; i++) {
    for(int j = 0; j <= m; j++) {
        if(j < v[i]) 
            f[i][j] = f[i-1][j];
        else 
            f[i][j] = max(f[i-1][j], f[i][j-v[i]] + w[i]); // 关键区别：f[i][j-v[i]]
    }
}
cout << f[n][m] << endl;
```

#### 方案3：优化空间的迭代DP
```cpp
int f[N] = {0};
for(int i = 1; i <= n; i++) {
    for(int j = v[i]; j <= m; j++) { // 正序循环
        f[j] = max(f[j], f[j-v[i]] + w[i]);
    }
}
cout << f[m] << endl;
```

