要将二级指针转换为一级指针的形式，我们需要修改函数参数和调用方式。主要改动点在于：

1. 函数参数从`node** head`改为`node* head`
2. 函数返回值改为新的头节点指针
3. 调用方式需要接收返回值来更新头指针

以下是修改后的代码：

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    int data;
    struct node* next;
} node;

node* head_insert(node* head, int n) {
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        node* new_node = (node*)malloc(sizeof(node));
        new_node->data = x;
        new_node->next = head;
        head = new_node;
    }
    return head;
}

node* tail_insert(node* head, int n) {
    node* tail = NULL;
    if (head != NULL) {
        tail = head;
        while (tail->next != NULL) {
            tail = tail->next;
        }
    }

    for (int i = 0; i < n; i++) {
        node* new_node = (node*)malloc(sizeof(node));
        int x;
        scanf("%d", &x);
        new_node->data = x;
        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }
    return head;
}

void print_list(node* head) {
    node* temp = head;
    while (temp != NULL) {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

node* reverse_list(node* head) {
    node* pre = NULL;
    node* curr = head;
    node* next = NULL;
    while (curr != NULL) {
        next = curr->next;
        curr->next = pre;
        pre = curr;
        curr = next;
    }
    return pre;
}

int main() {
    int n;
    scanf("%d", &n);
    node* head = NULL;
    head = head_insert(head, n);
    print_list(head);
    head = reverse_list(head);
    print_list(head);
    // head = tail_insert(head, n);
    // print_list(head);

    return 0;
}
```

主要变化：
1. `head_insert`和`tail_insert`现在返回新的头节点指针
2. 在`main`函数中，调用这些函数时需要接收返回值来更新`head`指针
3. `reverse_list`保持不变，因为它已经使用了一级指针的形式

这种修改使代码更直观，因为头指针的更新通过返回值明确表现出来，而不是通过隐式的指针间接修改。

