struct SeqList {
    int data[100];
    int length;
};

void SLInit(SeqList &list);

// SeqList.cpp
#include "SeqList.h"

void SLInit(SeqList &list) {
    list.length = 0;
}

// Test.cpp
#include "SeqList.h"

int main() {
    SeqList list;
    SLInit(list); // 调用初始化函数
    return 0;
}
```

### 编译命令：
```bash
